// ---- Registry services ----------------------------------------------------

const ControlDefinition* find_control(const char* ctrl_id) {
    if (!ctrl_id || std::strncmp(ctrl_id, "CTRL", 4) != 0) return nullptr;
    const int idx = std::atoi(ctrl_id + 4);
    if (idx < 1 || idx > static_cast<int>(sizeof(k_all_controls) / sizeof(k_all_controls[0])))
        return nullptr;
    return &k_all_controls[idx - 1];
}

bool control_registry_integrity_check() {
    constexpr size_t k_count = sizeof(k_all_controls) / sizeof(k_all_controls[0]);
    constexpr size_t k_secs = sizeof(k_all_sections) / sizeof(k_all_sections[0]);
    for (size_t i = 0; i < k_count; ++i) {
        const ControlDefinition& d = k_all_controls[i];
        char expected[16];
        std::snprintf(expected, sizeof(expected), "CTRL%03zu", i + 1);
        if (!d.id || std::strcmp(d.id, expected) != 0) return false;
        if (!d.section || !d.label || !d.category || !d.draw_label) return false;

        const bool is_value = (d.kind == ControlKind::SliderFloat ||
                               d.kind == ControlKind::SliderInt ||
                               d.kind == ControlKind::Toggle ||
                               d.kind == ControlKind::ColorEdit4 ||
                               d.kind == ControlKind::InputText);
        int resolvers = (d.resolve_float ? 1 : 0) + (d.resolve_int ? 1 : 0) +
                        (d.resolve_bool ? 1 : 0) + (d.resolve_color ? 1 : 0) +
                        (d.resolve_text ? 1 : 0);
        // CTRL047-049: per-selected-seed toggles bind indexed vectors;
        // rendered panel-locally, so they carry no direct resolver.
        const bool indexed_toggle = (i >= 46 && i <= 48) &&
                                    d.kind == ControlKind::Toggle;
        if (is_value && !indexed_toggle && resolvers != 1) return false;
        if (indexed_toggle && resolvers != 0) return false;
        if (!is_value && resolvers != 0) return false;
    }
    // Section views must tile the registry contiguously and in order.
    size_t covered = 0;
    for (size_t s = 0; s < k_secs; ++s) {
        const ControlSectionView& v = k_all_sections[s];
        if (v.defs != k_all_controls + covered) return false;
        covered += v.count;
    }
    return covered == k_count;
}

// ---- Generic value-control renderer ----------------------------------------

// v24.15 Track F R2-HF2: body of render_control, now reached only through
// the ImGui-ID-scoped wrapper below (see the wrapper comment for the
// duplicate-draw_label collision this structure fixes).
static bool render_control_value(const ControlDefinition& def, AppState& state,
                                 const float* f_min_override, const float* f_max_override) {
    switch (def.kind) {
    case ControlKind::SliderFloat: {
        float* v = def.resolve_float ? def.resolve_float(state) : nullptr;
        if (!v) return false;
        const float lo = f_min_override ? *f_min_override : def.f_min;
        const float hi = f_max_override ? *f_max_override : def.f_max;
        const float old_val = *v;
        if (render_compact_slider_float(def.draw_label, v, lo, hi, def.format)) {
            if (def.logs) log_ui_interaction(def.id, old_val, *v, def.unit);
            return true;
        }
        return false;
    }
    case ControlKind::SliderInt: {
        int* v = def.resolve_int ? def.resolve_int(state) : nullptr;
        if (!v) return false;
        const int old_val = *v;
        if (render_compact_slider_int(def.draw_label, v, def.i_min, def.i_max, def.format)) {
            if (def.logs) log_ui_interaction(def.id, static_cast<float>(old_val),
                                             static_cast<float>(*v), def.unit);
            return true;
        }
        return false;
    }
    case ControlKind::Toggle: {
        bool* v = def.resolve_bool ? def.resolve_bool(state) : nullptr;
        if (!v) return false;
        const bool old_val = *v;
        if (render_toggle_switch(def.draw_label, v)) {
            if (def.logs) log_ui_interaction(def.id, old_val ? 1.0f : 0.0f,
                                             *v ? 1.0f : 0.0f, def.unit);
            return true;
        }
        return false;
    }
    case ControlKind::ColorEdit4: {
        glm::vec4* v = def.resolve_color ? def.resolve_color(state) : nullptr;
        if (!v) return false;
        const glm::vec4 old_val = *v;
        const ImGuiColorEditFlags flags = ImGuiColorEditFlags_NoInputs |
                                          ImGuiColorEditFlags_AlphaBar |
                                          ImGuiColorEditFlags_AlphaPreviewHalf;
        if (ImGui::ColorEdit4(def.draw_label, &v->x, flags)) {
            if (def.logs) {
                char details[128];
                std::snprintf(details, sizeof(details),
                              "rgba(%.3f,%.3f,%.3f,%.3f) -> rgba(%.3f,%.3f,%.3f,%.3f)",
                              old_val.x, old_val.y, old_val.z, old_val.w,
                              v->x, v->y, v->z, v->w);
                log_ui_interaction(def.id, 0.0f, 0.0f, details);
            }
            return true;
        }
        return false;
    }
    case ControlKind::InputText: {
        char* v = def.resolve_text ? def.resolve_text(state) : nullptr;
        if (!v) return false;
        // CTRL057 buffer capacity is fixed by AppUIState (64 bytes incl. NUL).
        return ImGui::InputText(def.draw_label, v, sizeof(AppUIState::new_preset_name));
    }
    case ControlKind::Button:
    case ControlKind::PillButton:
    case ControlKind::Combo:
    case ControlKind::Selectable:
        // Action controls are rendered by their owning panel (layout-sensitive
        // SameLine chains, dynamic labels, accent colors); the registry row
        // exists for catalog, logging and benchmark enumeration.
        return false;
    }
    return false;
}

bool render_control(const ControlDefinition& def, AppState& state,
                    const float* f_min_override, const float* f_max_override) {
    // v24.15 Track F R2-HF2: ImGui ID-conflict fix. The compact widgets
    // (render_compact_slider_float / _int, render_toggle_switch) seed their
    // ID stack from the draw label alone (PushID(label)), so two registry
    // controls that share a draw label inside one ImGui window collapsed
    // onto the same ImGuiID. The Growth window carried exactly that: three
    // "Branch Angle" rows (CTRL016 Murray / CTRL040 Lateral Roots / CTRL246
    // Developmental; mode 2 co-renders CTRL016+CTRL040, mode 4 co-renders
    // CTRL246+CTRL040). One shared active ID made IsItemActive() true for
    // BOTH track submissions, so dragging one slider wrote every duplicate's
    // bound value, and the shared edit id (g_active_slider_edit_id) opened
    // the value-edit box on both rows at once. Prefixing the ID stack with
    // the registry's unique CTRL id makes every control's item and edit IDs
    // unique per window. Zero visual change (PushID draws nothing), zero
    // catalog impact (draw labels, CSV and inventory stay pinned), modes
    // 0-3 engine behavior untouched.
    ImGui::PushID(def.id);
    const bool changed = render_control_value(def, state, f_min_override, f_max_override);
    ImGui::PopID();
    return changed;
}

void log_control_interaction(const ControlDefinition& def,
                             float old_val, float new_val) {
    log_ui_interaction(def.id, old_val, new_val, def.unit);
}

